# ============================================================================
# Reproducible execution script for "{{TITLE}}"
# ============================================================================
# Runs the full analysis pipeline sequentially. Every script in scripts/
# whose name matches NN_*.R is sourced in numeric order, each in its own
# environment: a script reads its inputs from data/ (and data/processed/) and
# writes its outputs to data/processed/ and results/, so any of them can also
# be run on its own once the previous ones have been run.
#
# Generated by DisentFunSpaces {{DFS_VERSION}} on {{DATE}}.
# ============================================================================

# 0. Base path of the project --------------------------------------------------
# This script does not change the working directory: run it from the project
# folder (open the .Rproj file in RStudio, or source("run_all.R", chdir = TRUE)
# from anywhere else).
if (!file.exists("run_all.R") || !dir.exists("scripts"))
  stop("Run this script from the project folder: open the .Rproj file, or use ",
       "source(\"<path to the project>/run_all.R\", chdir = TRUE).", call. = FALSE)

# 1. Environment ---------------------------------------------------------------
# This script installs nothing. If a renv lockfile is present (renv::snapshot()
# creates one), the recorded package versions can be restored beforehand with
# renv::restore().
if (file.exists("renv.lock"))
  message("A renv.lock file is present: run renv::restore() beforehand to use ",
          "the package versions recorded for this project.")
for (d in c("data/processed", "results/figures", "results/tables"))
  dir.create(d, recursive = TRUE, showWarnings = FALSE)

# 2. Run every numbered script in order ----------------------------------------
script_paths <- sort(list.files("scripts", pattern = "^[0-9]{2}_.*\\.R$", full.names = TRUE))
script_paths <- script_paths[basename(script_paths) != "00_START_GeneralScript.R"]
cat("Scripts to execute:\n", paste(basename(script_paths), collapse = "\n"), "\n\n")

t0 <- Sys.time()
for (script in script_paths) {
  cat(">> Loading:", basename(script), "...\n")
  t1 <- Sys.time()
  tryCatch(
    source(script, local = new.env(parent = globalenv()), echo = FALSE),
    error = function(e) {
      message("ERROR in ", basename(script), ": ", conditionMessage(e))
      stop("STOP", call. = FALSE)
    }
  )
  cat("OK  Done:", basename(script),
      sprintf("(%.1f s)", as.numeric(difftime(Sys.time(), t1, units = "secs"))), "\n\n")
}

# 3. The Methods & Results report ----------------------------------------------
if (requireNamespace("rmarkdown", quietly = TRUE) && rmarkdown::pandoc_available()) {
  rmarkdown::render("report/Methods_Results.Rmd", quiet = TRUE,
                    envir = new.env(parent = globalenv()))
  cat("OK  Report: report/Methods_Results.docx\n")
} else {
  message("rmarkdown/pandoc not available: knit report/Methods_Results.Rmd in RStudio.")
}

writeLines(capture.output(sessionInfo()), "session_info.txt")
cat(sprintf("All scripts have been run successfully (%.1f min).\n",
            as.numeric(difftime(Sys.time(), t0, units = "mins"))))
